DO $dairy$
DECLARE payload jsonb := $payload$[{"language": "es", "slug": "queso-crema-casero", "public_path": "/queso-crema-casero", "title": "Queso crema casero para untar, con leche y crema", "excerpt": "Haz queso crema casero para untar con leche, crema y limón. Fotos para cuajar, escurrir y triturar, con consejos de textura y conservación en nevera.", "summary": "Un queso fresco de acidificación rápida, triturado hasta quedar untable. No lleva cultivo ni espesantes. Con leche y crema salen aproximadamente 350–450 g; calculamos 400 g. Necesitas termómetro, colador con tela y procesadora.", "content_html": "<p>Un queso fresco de acidificación rápida, triturado hasta quedar untable. No lleva cultivo ni espesantes. Con leche y crema salen aproximadamente 350–450 g; calculamos 400 g. Necesitas termómetro, colador con tela y procesadora.</p>", "notes": "<h3>Consejos y conservación</h3><p>Usa en 3–4 días. Es una versión rápida para untar; humedad, acidez y grasa difieren de un queso crema comercial fermentado. No se garantiza sustitución directa en cheesecakes o coberturas que dependan de una fórmula específica. Limón extra excluido de nutrición. Sin prueba de cocina propia. Contiene leche. Usa utensilios limpios y desinfectados y conserva a 4 °C o menos. No es una conserva para guardar a temperatura ambiente.</p><ul><li><a href=\"https://www.biggerbolderbaking.com/how-to-make-cream-cheese/\">Bigger Bolder Baking — acid-set spreadable fresh cheese technique</a></li><li><a href=\"https://pubs.nmsu.edu/_e/E216/\">New Mexico State University — cheesemaking</a></li></ul>", "ingredients": [{"name": "leche entera pasteurizada no UHT", "amount": "1000", "unit": "ml"}, {"name": "crema de leche pasteurizada, aproximadamente 35 % de grasa", "amount": "200", "unit": "ml"}, {"name": "zumo de limón recién exprimido y colado", "amount": "45", "unit": "ml"}, {"name": "sal fina", "amount": "3", "unit": "g"}], "steps": [{"title": "Calienta y cuaja", "content": "Limpia y desinfecta el equipo. Calienta leche y crema a 88–90 °C removiendo. Retira, añade el limón y mezcla suavemente. Reposa 10 minutos hasta separar copos blancos y suero. Si hace falta, añade hasta 15 ml más de limón y espera 5 minutos.", "image_url": "https://manualdecocina.com/recetas/queso-crema-casero/paso-01.webp", "image_alt": "Calienta y cuaja — Queso crema casero para untar, con leche y crema"}, {"title": "Escurre poco tiempo", "content": "Recoge los copos en una tela fina sobre un colador y bol. Deja escurrir 15 minutos sin apretar. Reserva un poco del líquido limpio para ajustar textura; no dejes que la cuajada se seque.", "image_url": "https://manualdecocina.com/recetas/queso-crema-casero/paso-02.webp", "image_alt": "Escurre poco tiempo — Queso crema casero para untar, con leche y crema"}, {"title": "Tritura hasta alisar", "content": "Pasa a la procesadora con la sal. Tritura 2–4 minutos, parando para bajar los bordes, hasta que esté suave. Si queda granuloso, añade el líquido reservado de cucharadita en cucharadita, solo lo necesario.", "image_url": "https://manualdecocina.com/recetas/queso-crema-casero/paso-03.webp", "image_alt": "Tritura hasta alisar — Queso crema casero para untar, con leche y crema"}, {"title": "Enfría y utiliza", "content": "Pasa a un recipiente limpio y cerrado y refrigera 2 horas. Sirve para untar o en dips. Tras enfriar debe sostener un surco de cuchara pero extenderse con facilidad.", "image_url": "https://manualdecocina.com/recetas/queso-crema-casero/paso-04.webp", "image_alt": "Enfría y utiliza — Queso crema casero para untar, con leche y crema"}], "category": "Guarniciones", "course": "Guarniciones", "cuisine": "Internacional", "difficulty": "Fácil", "prep_time_minutes": 15, "cook_time_minutes": 15, "total_time_minutes": 175, "servings": 16, "image_url": "https://manualdecocina.com/recetas/queso-crema-casero/portada.webp", "gallery": [{"url": "https://manualdecocina.com/recetas/queso-crema-casero/portada.webp", "alt": "Queso crema casero para untar, con leche y crema"}], "video_urls": [], "keywords": ["Queso crema casero para untar, con leche y crema"], "nutrition": {"calories": 86, "protein_g": 1.5, "carbs_g": 1, "fat_g": 8.5, "serving_size": "1 de 16 porciones, unos 25 g", "estimated": true, "note": "Estimación por porción; el rendimiento, la humedad y la marca cambian los valores.", "source": "Generic full-fat cream cheese finished-product proxy, USDA FoodData Central", "method": "Per 100 g proxy:344 kcal,6 g protein,4 g carbohydrate,34 g fat, multiplied by0.25 per25 g serving. Assumed yield400 g; milk/cream curd retention not measured and whey excluded. Approximation, not analytical nutrition."}, "seo": {"title": "Queso crema casero para untar, con leche y crema", "description": "Haz queso crema casero para untar con leche, crema y limón. Fotos para cuajar, escurrir y triturar, con consejos de textura y conservación en nevera.", "author": "Néstor Bastidas", "image_alt": "Queso crema casero para untar, con leche y crema", "image_variants": ["https://manualdecocina.com/recetas/queso-crema-casero/portada-1x1.webp", "https://manualdecocina.com/recetas/queso-crema-casero/portada-4x3.webp", "https://manualdecocina.com/recetas/queso-crema-casero/portada-16x9.webp"], "faq": [{"q": "¿Por qué queda granulado?", "a": "Puede haberse secado demasiado o faltar triturado. Añade poco líquido reservado y procesa de nuevo."}, {"q": "¿Puedo usar solo leche?", "a": "Cambian grasa, rendimiento y textura. Esta fórmula incluye crema para obtener una pasta más untuosa."}], "additional_time_minutes": 145}, "published": false, "editorial_status": "ready"}, {"language": "en", "slug": "homemade-spreadable-cream-cheese", "public_path": "/en/homemade-spreadable-cream-cheese", "title": "Homemade spreadable cream cheese with milk and cream", "excerpt": "Make quick spreadable cream cheese with milk, cream and lemon. Photos show setting, draining and blending, with texture tips and refrigerator storage.", "summary": "A quick acid-set fresh cheese blended until spreadable, without added cultures or thickeners. Milk and cream yield about 350–450 g; we assume 400 g. Use a thermometer, cloth-lined strainer and food processor.", "content_html": "<p>A quick acid-set fresh cheese blended until spreadable, without added cultures or thickeners. Milk and cream yield about 350–450 g; we assume 400 g. Use a thermometer, cloth-lined strainer and food processor.</p>", "notes": "<h3>Tips and storage</h3><p>Use within 3–4 days. This quick spread differs in moisture, acidity and fat from cultured commercial cream cheese. A direct swap is not guaranteed in formula-dependent cheesecakes or frostings. Extra lemon excluded from nutrition. Not kitchen-tested. Contains milk. Use clean, sanitized equipment and refrigerate at 4 °C or below. This is not a shelf-stable canned product.</p><ul><li><a href=\"https://www.biggerbolderbaking.com/how-to-make-cream-cheese/\">Bigger Bolder Baking — acid-set spreadable fresh cheese technique</a></li><li><a href=\"https://pubs.nmsu.edu/_e/E216/\">New Mexico State University — cheesemaking</a></li></ul>", "ingredients": [{"name": "pasteurized whole milk, not UHT", "amount": "1000", "unit": "ml"}, {"name": "pasteurized heavy cream, approximately 35% fat", "amount": "200", "unit": "ml"}, {"name": "freshly squeezed strained lemon juice", "amount": "45", "unit": "ml"}, {"name": "fine salt", "amount": "3", "unit": "g"}], "steps": [{"title": "Heat and set", "content": "Sanitize equipment. Heat milk and cream to 88–90 °C while stirring. Remove from heat, add lemon and stir gently. Rest 10 minutes until white curds separate from whey. If needed, add up to 15 ml extra lemon and wait 5 minutes.", "image_url": "https://manualdecocina.com/recetas/queso-crema-casero/paso-01.webp", "image_alt": "Heat and set — Homemade spreadable cream cheese with milk and cream"}, {"title": "Drain briefly", "content": "Ladle into fine cloth in a strainer over a bowl. Drain for 15 minutes without squeezing. Reserve some clean liquid to adjust texture; avoid drying the curds.", "image_url": "https://manualdecocina.com/recetas/queso-crema-casero/paso-02.webp", "image_alt": "Drain briefly — Homemade spreadable cream cheese with milk and cream"}, {"title": "Blend until smooth", "content": "Process curds with salt for 2–4 minutes, stopping to scrape the sides. If grainy, add reserved liquid a teaspoon at a time, only as needed, and blend again.", "image_url": "https://manualdecocina.com/recetas/queso-crema-casero/paso-03.webp", "image_alt": "Blend until smooth — Homemade spreadable cream cheese with milk and cream"}, {"title": "Chill and use", "content": "Transfer to a clean covered container and refrigerate for 2 hours. Use as a spread or in dips. Once chilled, it should hold a spoon groove while spreading easily.", "image_url": "https://manualdecocina.com/recetas/queso-crema-casero/paso-04.webp", "image_alt": "Chill and use — Homemade spreadable cream cheese with milk and cream"}], "category": "Side dishes", "course": "Side dishes", "cuisine": "International", "difficulty": "Easy", "prep_time_minutes": 15, "cook_time_minutes": 15, "total_time_minutes": 175, "servings": 16, "image_url": "https://manualdecocina.com/recetas/queso-crema-casero/portada.webp", "gallery": [{"url": "https://manualdecocina.com/recetas/queso-crema-casero/portada.webp", "alt": "Homemade spreadable cream cheese with milk and cream"}], "video_urls": [], "keywords": ["Homemade spreadable cream cheese with milk and cream"], "nutrition": {"calories": 86, "protein_g": 1.5, "carbs_g": 1, "fat_g": 8.5, "serving_size": "1 of 16 servings, about 25 g", "estimated": true, "note": "Estimated per serving; yield, moisture and brands affect the values.", "source": "Generic full-fat cream cheese finished-product proxy, USDA FoodData Central", "method": "Per 100 g proxy:344 kcal,6 g protein,4 g carbohydrate,34 g fat, multiplied by0.25 per25 g serving. Assumed yield400 g; milk/cream curd retention not measured and whey excluded. Approximation, not analytical nutrition."}, "seo": {"title": "Homemade spreadable cream cheese with milk and cream", "description": "Make quick spreadable cream cheese with milk, cream and lemon. Photos show setting, draining and blending, with texture tips and refrigerator storage.", "author": "Néstor Bastidas", "image_alt": "Homemade spreadable cream cheese with milk and cream", "image_variants": ["https://manualdecocina.com/recetas/queso-crema-casero/portada-1x1.webp", "https://manualdecocina.com/recetas/queso-crema-casero/portada-4x3.webp", "https://manualdecocina.com/recetas/queso-crema-casero/portada-16x9.webp"], "faq": [{"q": "Why is it grainy?", "a": "It may be over-drained or under-blended. Add a little reserved liquid and process again."}, {"q": "Can I use milk alone?", "a": "Fat, yield and texture change. This formula includes cream for a richer spread."}], "additional_time_minutes": 145}, "published": false, "editorial_status": "ready"}, {"language": "de", "slug": "streichfrischkaese-selber-machen", "public_path": "/de/streichfrischkaese-selber-machen", "title": "Streichfrischkäse aus Milch und Sahne selber machen", "excerpt": "Schnellen Streichfrischkäse aus Milch, Sahne und Zitrone machen. Fotos erklären Gerinnen, Abtropfen und Pürieren sowie Konsistenz und gekühlte Aufbewahrung.", "summary": "Ein schnell gesäuerter Frischkäse, der ohne zugesetzte Kulturen oder Verdickungsmittel glatt püriert wird. Milch und Sahne ergeben etwa 350–450 g; gerechnet wird mit 400 g. Du brauchst Thermometer, Tuch, Sieb und Küchenmaschine.", "content_html": "<p>Ein schnell gesäuerter Frischkäse, der ohne zugesetzte Kulturen oder Verdickungsmittel glatt püriert wird. Milch und Sahne ergeben etwa 350–450 g; gerechnet wird mit 400 g. Du brauchst Thermometer, Tuch, Sieb und Küchenmaschine.</p>", "notes": "<h3>Tipps und Aufbewahrung</h3><p>In 3–4 Tagen verbrauchen. Feuchtigkeit, Säure und Fett unterscheiden sich von kultiviertem Industriefrischkäse. Ein direkter Ersatz in empfindlichen Käsekuchen oder Glasuren ist nicht garantiert. Zusätzlicher Saft nicht in Nährwerten enthalten. Nicht küchenerprobt. Enthält Milch. Saubere, desinfizierte Geräte verwenden und bei höchstens 4 °C lagern. Dies ist keine ungekühlt haltbare Konserve.</p><ul><li><a href=\"https://www.biggerbolderbaking.com/how-to-make-cream-cheese/\">Bigger Bolder Baking — acid-set spreadable fresh cheese technique</a></li><li><a href=\"https://pubs.nmsu.edu/_e/E216/\">New Mexico State University — cheesemaking</a></li></ul>", "ingredients": [{"name": "pasteurisierte Vollmilch, keine H-Milch", "amount": "1000", "unit": "ml"}, {"name": "pasteurisierte Sahne, etwa 35 % Fett", "amount": "200", "unit": "ml"}, {"name": "frisch gepresster abgesiebter Zitronensaft", "amount": "45", "unit": "ml"}, {"name": "feines Salz", "amount": "3", "unit": "g"}], "steps": [{"title": "Erhitzen und gerinnen", "content": "Geräte desinfizieren. Milch und Sahne unter Rühren auf 88–90 °C erhitzen. Vom Herd nehmen, Zitronensaft sanft einrühren. 10 Minuten ruhen lassen, bis Flocken und Molke entstehen. Bei Bedarf bis zu 15 ml zusätzlichen Saft zugeben und 5 Minuten warten.", "image_url": "https://manualdecocina.com/recetas/queso-crema-casero/paso-01.webp", "image_alt": "Erhitzen und gerinnen — Streichfrischkäse aus Milch und Sahne selber machen"}, {"title": "Kurz abtropfen", "content": "In ein feines Tuch im Sieb über einer Schüssel geben. 15 Minuten ohne Pressen abtropfen. Etwas saubere Flüssigkeit aufheben; die Flocken nicht austrocknen lassen.", "image_url": "https://manualdecocina.com/recetas/queso-crema-casero/paso-02.webp", "image_alt": "Kurz abtropfen — Streichfrischkäse aus Milch und Sahne selber machen"}, {"title": "Glatt pürieren", "content": "Mit Salz 2–4 Minuten pürieren, zwischendurch die Ränder abstreifen. Bei körniger Konsistenz aufgehobene Flüssigkeit teelöffelweise sparsam zugeben und weiterpürieren.", "image_url": "https://manualdecocina.com/recetas/queso-crema-casero/paso-03.webp", "image_alt": "Glatt pürieren — Streichfrischkäse aus Milch und Sahne selber machen"}, {"title": "Kühlen und verwenden", "content": "In einer sauberen geschlossenen Dose 2 Stunden kühlen. Als Aufstrich oder für Dips verwenden. Gekühlt sollte die Creme eine Löffelspur halten und leicht streichbar sein.", "image_url": "https://manualdecocina.com/recetas/queso-crema-casero/paso-04.webp", "image_alt": "Kühlen und verwenden — Streichfrischkäse aus Milch und Sahne selber machen"}], "category": "Beilagen", "course": "Beilagen", "cuisine": "International", "difficulty": "Einfach", "prep_time_minutes": 15, "cook_time_minutes": 15, "total_time_minutes": 175, "servings": 16, "image_url": "https://manualdecocina.com/recetas/queso-crema-casero/portada.webp", "gallery": [{"url": "https://manualdecocina.com/recetas/queso-crema-casero/portada.webp", "alt": "Streichfrischkäse aus Milch und Sahne selber machen"}], "video_urls": [], "keywords": ["Streichfrischkäse aus Milch und Sahne selber machen"], "nutrition": {"calories": 86, "protein_g": 1.5, "carbs_g": 1, "fat_g": 8.5, "serving_size": "1 von 16 Portionen, etwa 25 g", "estimated": true, "note": "Schätzung pro Portion; Ausbeute, Feuchtigkeit und Produkte beeinflussen die Werte.", "source": "Generic full-fat cream cheese finished-product proxy, USDA FoodData Central", "method": "Per 100 g proxy:344 kcal,6 g protein,4 g carbohydrate,34 g fat, multiplied by0.25 per25 g serving. Assumed yield400 g; milk/cream curd retention not measured and whey excluded. Approximation, not analytical nutrition."}, "seo": {"title": "Streichfrischkäse aus Milch und Sahne selber machen", "description": "Schnellen Streichfrischkäse aus Milch, Sahne und Zitrone machen. Fotos erklären Gerinnen, Abtropfen und Pürieren sowie Konsistenz und gekühlte Aufbewahrung.", "author": "Néstor Bastidas", "image_alt": "Streichfrischkäse aus Milch und Sahne selber machen", "image_variants": ["https://manualdecocina.com/recetas/queso-crema-casero/portada-1x1.webp", "https://manualdecocina.com/recetas/queso-crema-casero/portada-4x3.webp", "https://manualdecocina.com/recetas/queso-crema-casero/portada-16x9.webp"], "faq": [{"q": "Warum bleibt er körnig?", "a": "Möglicherweise zu trocken oder zu kurz püriert. Etwas Flüssigkeit zugeben und weiterpürieren."}, {"q": "Geht es nur mit Milch?", "a": "Fett, Menge und Konsistenz ändern sich. Dieses Rezept enthält Sahne für mehr Cremigkeit."}], "additional_time_minutes": 145}, "published": false, "editorial_status": "ready"}, {"language": "fr", "slug": "fromage-frais-a-tartiner-maison", "public_path": "/fr/fromage-frais-a-tartiner-maison", "title": "Fromage frais maison à tartiner, lait et crème", "excerpt": "Faites un fromage frais à tartiner avec lait, crème et citron. Photos du caillage, de l'égouttage et du mixage, conseils de texture et conservation au frais.", "summary": "Un fromage frais acidifié rapidement puis mixé, sans ferments ajoutés ni épaississant. Lait et crème donnent environ 350–450 g ; nous comptons 400 g. Prévoyez thermomètre, tissu, passoire et robot.", "content_html": "<p>Un fromage frais acidifié rapidement puis mixé, sans ferments ajoutés ni épaississant. Lait et crème donnent environ 350–450 g ; nous comptons 400 g. Prévoyez thermomètre, tissu, passoire et robot.</p>", "notes": "<h3>Conseils et conservation</h3><p>Utilisez sous 3–4 jours. Humidité, acidité et matière grasse diffèrent d&#x27;un cream cheese industriel fermenté. La substitution directe n&#x27;est pas garantie pour cheesecakes ou glaçages à formule précise. Citron supplémentaire exclu de la nutrition. Non testée en cuisine. Contient du lait. Utilisez du matériel propre et désinfecté et conservez à 4 °C maximum. Cette préparation ne se conserve pas à température ambiante.</p><ul><li><a href=\"https://www.biggerbolderbaking.com/how-to-make-cream-cheese/\">Bigger Bolder Baking — acid-set spreadable fresh cheese technique</a></li><li><a href=\"https://pubs.nmsu.edu/_e/E216/\">New Mexico State University — cheesemaking</a></li></ul>", "ingredients": [{"name": "lait entier pasteurisé non UHT", "amount": "1000", "unit": "ml"}, {"name": "crème entière pasteurisée, environ 35 % de matière grasse", "amount": "200", "unit": "ml"}, {"name": "jus de citron fraîchement pressé et filtré", "amount": "45", "unit": "ml"}, {"name": "sel fin", "amount": "3", "unit": "g"}], "steps": [{"title": "Chauffez et faites cailler", "content": "Désinfectez le matériel. Chauffez lait et crème à 88–90 °C en remuant. Retirez du feu, ajoutez le citron et mélangez doucement. Reposez 10 minutes jusqu'à séparation. Si nécessaire, ajoutez jusqu'à 15 ml de citron et attendez 5 minutes.", "image_url": "https://manualdecocina.com/recetas/queso-crema-casero/paso-01.webp", "image_alt": "Chauffez et faites cailler — Fromage frais maison à tartiner, lait et crème"}, {"title": "Égouttez brièvement", "content": "Recueillez dans un tissu fin sur une passoire et un bol. Égouttez 15 minutes sans serrer. Réservez du liquide propre pour ajuster la texture ; ne desséchez pas le caillé.", "image_url": "https://manualdecocina.com/recetas/queso-crema-casero/paso-02.webp", "image_alt": "Égouttez brièvement — Fromage frais maison à tartiner, lait et crème"}, {"title": "Mixez pour lisser", "content": "Mixez avec le sel 2–4 minutes en raclant les parois à l'arrêt. Si granuleux, ajoutez le liquide réservé cuillère à café par cuillère à café, juste assez, puis mixez.", "image_url": "https://manualdecocina.com/recetas/queso-crema-casero/paso-03.webp", "image_alt": "Mixez pour lisser — Fromage frais maison à tartiner, lait et crème"}, {"title": "Refroidissez et utilisez", "content": "Transférez en boîte propre fermée et réfrigérez 2 heures. Servez à tartiner ou dans des dips. La crème froide doit garder un sillon de cuillère tout en s'étalant facilement.", "image_url": "https://manualdecocina.com/recetas/queso-crema-casero/paso-04.webp", "image_alt": "Refroidissez et utilisez — Fromage frais maison à tartiner, lait et crème"}], "category": "Accompagnements", "course": "Accompagnements", "cuisine": "Internationale", "difficulty": "Facile", "prep_time_minutes": 15, "cook_time_minutes": 15, "total_time_minutes": 175, "servings": 16, "image_url": "https://manualdecocina.com/recetas/queso-crema-casero/portada.webp", "gallery": [{"url": "https://manualdecocina.com/recetas/queso-crema-casero/portada.webp", "alt": "Fromage frais maison à tartiner, lait et crème"}], "video_urls": [], "keywords": ["Fromage frais maison à tartiner, lait et crème"], "nutrition": {"calories": 86, "protein_g": 1.5, "carbs_g": 1, "fat_g": 8.5, "serving_size": "1 des 16 portions, environ 25 g", "estimated": true, "note": "Estimation par portion ; rendement, humidité et marques modifient les valeurs.", "source": "Generic full-fat cream cheese finished-product proxy, USDA FoodData Central", "method": "Per 100 g proxy:344 kcal,6 g protein,4 g carbohydrate,34 g fat, multiplied by0.25 per25 g serving. Assumed yield400 g; milk/cream curd retention not measured and whey excluded. Approximation, not analytical nutrition."}, "seo": {"title": "Fromage frais maison à tartiner, lait et crème", "description": "Faites un fromage frais à tartiner avec lait, crème et citron. Photos du caillage, de l'égouttage et du mixage, conseils de texture et conservation au frais.", "author": "Néstor Bastidas", "image_alt": "Fromage frais maison à tartiner, lait et crème", "image_variants": ["https://manualdecocina.com/recetas/queso-crema-casero/portada-1x1.webp", "https://manualdecocina.com/recetas/queso-crema-casero/portada-4x3.webp", "https://manualdecocina.com/recetas/queso-crema-casero/portada-16x9.webp"], "faq": [{"q": "Pourquoi est-il granuleux ?", "a": "Il peut être trop égoutté ou insuffisamment mixé. Ajoutez un peu de liquide et mixez à nouveau."}, {"q": "Puis-je utiliser seulement du lait ?", "a": "Matière grasse, rendement et texture changent. La crème apporte ici de l'onctuosité."}], "additional_time_minutes": 145}, "published": false, "editorial_status": "ready"}, {"language": "it", "slug": "formaggio-cremoso-spalmabile-casalingo", "public_path": "/it/formaggio-cremoso-spalmabile-casalingo", "title": "Formaggio cremoso da spalmare fatto in casa", "excerpt": "Prepara formaggio spalmabile con latte, panna e limone. Foto di coagulazione, scolatura e frullatura, con consigli sulla consistenza e conservazione in frigo.", "summary": "Un formaggio fresco acidificato rapidamente e frullato, senza fermenti aggiunti o addensanti. Latte e panna rendono circa 350–450 g; calcoliamo 400 g. Servono termometro, telo, colino e robot da cucina.", "content_html": "<p>Un formaggio fresco acidificato rapidamente e frullato, senza fermenti aggiunti o addensanti. Latte e panna rendono circa 350–450 g; calcoliamo 400 g. Servono termometro, telo, colino e robot da cucina.</p>", "notes": "<h3>Consigli e conservazione</h3><p>Usa entro 3–4 giorni. Umidità, acidità e grassi differiscono dal formaggio cremoso commerciale fermentato. Non è garantita sostituzione diretta in cheesecake o coperture con formule precise. Limone extra escluso dalla nutrizione. Non testato in cucina. Contiene latte. Usa utensili puliti e igienizzati e conserva a 4 °C o meno. Non è una conserva da tenere a temperatura ambiente.</p><ul><li><a href=\"https://www.biggerbolderbaking.com/how-to-make-cream-cheese/\">Bigger Bolder Baking — acid-set spreadable fresh cheese technique</a></li><li><a href=\"https://pubs.nmsu.edu/_e/E216/\">New Mexico State University — cheesemaking</a></li></ul>", "ingredients": [{"name": "latte intero pastorizzato non UHT", "amount": "1000", "unit": "ml"}, {"name": "panna pastorizzata, circa 35% di grassi", "amount": "200", "unit": "ml"}, {"name": "succo di limone appena spremuto e filtrato", "amount": "45", "unit": "ml"}, {"name": "sale fino", "amount": "3", "unit": "g"}], "steps": [{"title": "Scalda e coagula", "content": "Igienizza l'attrezzatura. Porta latte e panna a 88–90 °C mescolando. Togli dal fuoco, aggiungi limone e mescola piano. Riposa 10 minuti finché si separano fiocchi e siero. Se serve, aggiungi fino a 15 ml di limone e attendi 5 minuti.", "image_url": "https://manualdecocina.com/recetas/queso-crema-casero/paso-01.webp", "image_alt": "Scalda e coagula — Formaggio cremoso da spalmare fatto in casa"}, {"title": "Scola brevemente", "content": "Raccogli nel telo fine sopra colino e ciotola. Scola 15 minuti senza strizzare. Conserva poco liquido pulito per regolare la consistenza; non asciugare troppo la cagliata.", "image_url": "https://manualdecocina.com/recetas/queso-crema-casero/paso-02.webp", "image_alt": "Scola brevemente — Formaggio cremoso da spalmare fatto in casa"}, {"title": "Frulla fino a lisciare", "content": "Frulla con il sale per 2–4 minuti, fermandoti per raschiare le pareti. Se granuloso, aggiungi liquido a cucchiaini, solo quanto serve, e frulla ancora.", "image_url": "https://manualdecocina.com/recetas/queso-crema-casero/paso-03.webp", "image_alt": "Frulla fino a lisciare — Formaggio cremoso da spalmare fatto in casa"}, {"title": "Raffredda e usa", "content": "Trasferisci in contenitore pulito e chiuso e refrigera 2 ore. Usa da spalmare o nelle salse. Freddo deve mantenere il solco del cucchiaio ma stendersi facilmente.", "image_url": "https://manualdecocina.com/recetas/queso-crema-casero/paso-04.webp", "image_alt": "Raffredda e usa — Formaggio cremoso da spalmare fatto in casa"}], "category": "Contorni", "course": "Contorni", "cuisine": "Internazionale", "difficulty": "Facile", "prep_time_minutes": 15, "cook_time_minutes": 15, "total_time_minutes": 175, "servings": 16, "image_url": "https://manualdecocina.com/recetas/queso-crema-casero/portada.webp", "gallery": [{"url": "https://manualdecocina.com/recetas/queso-crema-casero/portada.webp", "alt": "Formaggio cremoso da spalmare fatto in casa"}], "video_urls": [], "keywords": ["Formaggio cremoso da spalmare fatto in casa"], "nutrition": {"calories": 86, "protein_g": 1.5, "carbs_g": 1, "fat_g": 8.5, "serving_size": "1 di 16 porzioni, circa 25 g", "estimated": true, "note": "Stima per porzione; resa, umidità e prodotti possono cambiare i valori.", "source": "Generic full-fat cream cheese finished-product proxy, USDA FoodData Central", "method": "Per 100 g proxy:344 kcal,6 g protein,4 g carbohydrate,34 g fat, multiplied by0.25 per25 g serving. Assumed yield400 g; milk/cream curd retention not measured and whey excluded. Approximation, not analytical nutrition."}, "seo": {"title": "Formaggio cremoso da spalmare fatto in casa", "description": "Prepara formaggio spalmabile con latte, panna e limone. Foto di coagulazione, scolatura e frullatura, con consigli sulla consistenza e conservazione in frigo.", "author": "Néstor Bastidas", "image_alt": "Formaggio cremoso da spalmare fatto in casa", "image_variants": ["https://manualdecocina.com/recetas/queso-crema-casero/portada-1x1.webp", "https://manualdecocina.com/recetas/queso-crema-casero/portada-4x3.webp", "https://manualdecocina.com/recetas/queso-crema-casero/portada-16x9.webp"], "faq": [{"q": "Perché è granuloso?", "a": "Può essere troppo scolato o poco frullato. Aggiungi poco liquido e frulla ancora."}, {"q": "Posso usare solo latte?", "a": "Cambiano grassi, resa e consistenza. Questa formula include panna per maggiore cremosità."}], "additional_time_minutes": 145}, "published": false, "editorial_status": "ready"}, {"language": "ja", "slug": "homemade-spreadable-cream-cheese", "public_path": "/ja/homemade-spreadable-cream-cheese", "title": "牛乳とクリームで作る自家製クリームチーズ風スプレッド", "excerpt": "牛乳、クリーム、レモンで作る塗りやすいフレッシュチーズ。凝固、水切り、なめらかにする工程を写真で解説し、食感の調整と冷蔵保存の目安も紹介します。", "summary": "酸で短時間に固め、滑らかになるまで撹拌するフレッシュチーズです。菌や増粘剤は加えません。牛乳とクリームから約350〜450 g、ここでは400 gを想定します。温度計、布、ざる、フードプロセッサーが必要です。", "content_html": "<p>酸で短時間に固め、滑らかになるまで撹拌するフレッシュチーズです。菌や増粘剤は加えません。牛乳とクリームから約350〜450 g、ここでは400 gを想定します。温度計、布、ざる、フードプロセッサーが必要です。</p>", "notes": "<h3>コツと保存</h3><p>3〜4日以内に使います。市販の発酵クリームチーズとは水分、酸度、脂肪分が違います。配合が重要なチーズケーキやフロスティングに、そのまま置き換えられる保証はありません。追加のレモンは栄養推定に含めません。調理試験は行っていません。 乳を含みます。清潔に洗浄・消毒した器具を使い、4 ℃以下で冷蔵してください。常温保存用の瓶詰めではありません。</p><ul><li><a href=\"https://www.biggerbolderbaking.com/how-to-make-cream-cheese/\">Bigger Bolder Baking — acid-set spreadable fresh cheese technique</a></li><li><a href=\"https://pubs.nmsu.edu/_e/E216/\">New Mexico State University — cheesemaking</a></li></ul>", "ingredients": [{"name": "超高温殺菌ではない殺菌済み全乳", "amount": "1000", "unit": "ml"}, {"name": "殺菌済みの生クリーム、乳脂肪分約35％", "amount": "200", "unit": "ml"}, {"name": "搾りたてのレモン汁、こしたもの", "amount": "45", "unit": "ml"}, {"name": "細かい塩", "amount": "3", "unit": "g"}], "steps": [{"title": "温めて固める", "content": "器具を洗浄・消毒します。牛乳とクリームを混ぜながら88〜90 ℃にします。火を止めてレモン汁を加え、静かに混ぜます。10分休ませ、粒と乳清に分けます。必要ならレモン汁を最大15 ml足して5分待ちます。", "image_url": "https://manualdecocina.com/recetas/queso-crema-casero/paso-01.webp", "image_alt": "温めて固める — 牛乳とクリームで作る自家製クリームチーズ風スプレッド"}, {"title": "短く水切りする", "content": "ボウルにざると細かい布を重ね、粒を移します。絞らず15分水切りします。調整用に清潔な液体を少し残します。粒を乾かしすぎません。", "image_url": "https://manualdecocina.com/recetas/queso-crema-casero/paso-02.webp", "image_alt": "短く水切りする — 牛乳とクリームで作る自家製クリームチーズ風スプレッド"}, {"title": "滑らかにする", "content": "塩と一緒にプロセッサーに入れ、2〜4分撹拌します。途中で止めて縁を落とします。粒が残るなら、取り分けた液体を小さじずつ必要最小限加えて再び混ぜます。", "image_url": "https://manualdecocina.com/recetas/queso-crema-casero/paso-03.webp", "image_alt": "滑らかにする — 牛乳とクリームで作る自家製クリームチーズ風スプレッド"}, {"title": "冷やして使う", "content": "清潔なふた付き容器に入れ、2時間冷蔵します。パンに塗ったりディップに使ったりします。冷えるとスプーンの筋が残り、滑らかに塗れる固さになります。", "image_url": "https://manualdecocina.com/recetas/queso-crema-casero/paso-04.webp", "image_alt": "冷やして使う — 牛乳とクリームで作る自家製クリームチーズ風スプレッド"}], "category": "付け合わせ", "course": "付け合わせ", "cuisine": "各国料理", "difficulty": "簡単", "prep_time_minutes": 15, "cook_time_minutes": 15, "total_time_minutes": 175, "servings": 16, "image_url": "https://manualdecocina.com/recetas/queso-crema-casero/portada.webp", "gallery": [{"url": "https://manualdecocina.com/recetas/queso-crema-casero/portada.webp", "alt": "牛乳とクリームで作る自家製クリームチーズ風スプレッド"}], "video_urls": [], "keywords": ["牛乳とクリームで作る自家製クリームチーズ風スプレッド"], "nutrition": {"calories": 86, "protein_g": 1.5, "carbs_g": 1, "fat_g": 8.5, "serving_size": "16食分の1、約25 g", "estimated": true, "note": "1食分の推定値です。出来上がり量、水分、製品により異なります。", "source": "Generic full-fat cream cheese finished-product proxy, USDA FoodData Central", "method": "Per 100 g proxy:344 kcal,6 g protein,4 g carbohydrate,34 g fat, multiplied by0.25 per25 g serving. Assumed yield400 g; milk/cream curd retention not measured and whey excluded. Approximation, not analytical nutrition."}, "seo": {"title": "牛乳とクリームで作る自家製クリームチーズ風スプレッド", "description": "牛乳、クリーム、レモンで作る塗りやすいフレッシュチーズ。凝固、水切り、なめらかにする工程を写真で解説し、食感の調整と冷蔵保存の目安も紹介します。", "author": "Néstor Bastidas", "image_alt": "牛乳とクリームで作る自家製クリームチーズ風スプレッド", "image_variants": ["https://manualdecocina.com/recetas/queso-crema-casero/portada-1x1.webp", "https://manualdecocina.com/recetas/queso-crema-casero/portada-4x3.webp", "https://manualdecocina.com/recetas/queso-crema-casero/portada-16x9.webp"], "faq": [{"q": "粒が残るのはなぜですか。", "a": "水切りしすぎか撹拌不足が考えられます。残した液体を少し加え、もう一度混ぜます。"}, {"q": "牛乳だけでも作れますか。", "a": "脂肪分、量、食感が変わります。この配合では滑らかさのためクリームを使います。"}], "additional_time_minutes": 145}, "published": false, "editorial_status": "ready"}, {"language": "pt", "slug": "queijo-cremoso-caseiro-para-passar", "public_path": "/pt/queijo-cremoso-caseiro-para-passar", "title": "Queijo cremoso caseiro com leite e creme de leite", "excerpt": "Faça queijo cremoso para passar com leite, creme e limão. Fotos mostram coagulação, drenagem e processamento, com dicas de textura e conservação na geladeira.", "summary": "Queijo fresco de acidificação rápida, batido até ficar cremoso, sem culturas ou espessantes adicionados. Leite e creme rendem cerca de 350–450 g; calculamos 400 g. Use termômetro, pano, peneira e processador.", "content_html": "<p>Queijo fresco de acidificação rápida, batido até ficar cremoso, sem culturas ou espessantes adicionados. Leite e creme rendem cerca de 350–450 g; calculamos 400 g. Use termômetro, pano, peneira e processador.</p>", "notes": "<h3>Dicas e conservação</h3><p>Use em 3–4 dias. Umidade, acidez e gordura diferem de cream cheese comercial fermentado. Não se garante substituição direta em cheesecakes ou coberturas com fórmula específica. Limão extra excluído da nutrição. Sem teste de cozinha próprio. Contém leite. Use utensílios limpos e higienizados e conserve a 4 °C ou menos. Não é uma conserva para guardar à temperatura ambiente.</p><ul><li><a href=\"https://www.biggerbolderbaking.com/how-to-make-cream-cheese/\">Bigger Bolder Baking — acid-set spreadable fresh cheese technique</a></li><li><a href=\"https://pubs.nmsu.edu/_e/E216/\">New Mexico State University — cheesemaking</a></li></ul>", "ingredients": [{"name": "leite integral pasteurizado não UHT", "amount": "1000", "unit": "ml"}, {"name": "creme de leite pasteurizado, cerca de 35% de gordura", "amount": "200", "unit": "ml"}, {"name": "suco de limão espremido na hora e coado", "amount": "45", "unit": "ml"}, {"name": "sal fino", "amount": "3", "unit": "g"}], "steps": [{"title": "Aqueça e coalhe", "content": "Higienize o equipamento. Aqueça leite e creme a 88–90 °C mexendo. Retire, acrescente o limão e misture suavemente. Descanse 10 minutos até separar flocos e soro. Se necessário, adicione até 15 ml de limão e aguarde 5 minutos.", "image_url": "https://manualdecocina.com/recetas/queso-crema-casero/paso-01.webp", "image_alt": "Aqueça e coalhe — Queijo cremoso caseiro com leite e creme de leite"}, {"title": "Escorra brevemente", "content": "Recolha para pano fino sobre peneira e tigela. Escorra 15 minutos sem apertar. Reserve um pouco do líquido limpo para ajustar textura; não seque demais a coalhada.", "image_url": "https://manualdecocina.com/recetas/queso-crema-casero/paso-02.webp", "image_alt": "Escorra brevemente — Queijo cremoso caseiro com leite e creme de leite"}, {"title": "Bata até alisar", "content": "Processe com sal por 2–4 minutos, parando para raspar as laterais. Se ficar granulado, adicione líquido de colher de chá em colher de chá, só o necessário, e processe novamente.", "image_url": "https://manualdecocina.com/recetas/queso-crema-casero/paso-03.webp", "image_alt": "Bata até alisar — Queijo cremoso caseiro com leite e creme de leite"}, {"title": "Resfrie e use", "content": "Passe para recipiente limpo e fechado e refrigere por 2 horas. Sirva para passar ou em pastas. Frio deve manter um sulco de colher e espalhar facilmente.", "image_url": "https://manualdecocina.com/recetas/queso-crema-casero/paso-04.webp", "image_alt": "Resfrie e use — Queijo cremoso caseiro com leite e creme de leite"}], "category": "Acompanhamentos", "course": "Acompanhamentos", "cuisine": "Internacional", "difficulty": "Fácil", "prep_time_minutes": 15, "cook_time_minutes": 15, "total_time_minutes": 175, "servings": 16, "image_url": "https://manualdecocina.com/recetas/queso-crema-casero/portada.webp", "gallery": [{"url": "https://manualdecocina.com/recetas/queso-crema-casero/portada.webp", "alt": "Queijo cremoso caseiro com leite e creme de leite"}], "video_urls": [], "keywords": ["Queijo cremoso caseiro com leite e creme de leite"], "nutrition": {"calories": 86, "protein_g": 1.5, "carbs_g": 1, "fat_g": 8.5, "serving_size": "1 de 16 porções, cerca de 25 g", "estimated": true, "note": "Estimativa por porção; rendimento, umidade e marcas alteram os valores.", "source": "Generic full-fat cream cheese finished-product proxy, USDA FoodData Central", "method": "Per 100 g proxy:344 kcal,6 g protein,4 g carbohydrate,34 g fat, multiplied by0.25 per25 g serving. Assumed yield400 g; milk/cream curd retention not measured and whey excluded. Approximation, not analytical nutrition."}, "seo": {"title": "Queijo cremoso caseiro com leite e creme de leite", "description": "Faça queijo cremoso para passar com leite, creme e limão. Fotos mostram coagulação, drenagem e processamento, com dicas de textura e conservação na geladeira.", "author": "Néstor Bastidas", "image_alt": "Queijo cremoso caseiro com leite e creme de leite", "image_variants": ["https://manualdecocina.com/recetas/queso-crema-casero/portada-1x1.webp", "https://manualdecocina.com/recetas/queso-crema-casero/portada-4x3.webp", "https://manualdecocina.com/recetas/queso-crema-casero/portada-16x9.webp"], "faq": [{"q": "Por que fica granulado?", "a": "Pode ter escorrido demais ou faltado processamento. Acrescente pouco líquido reservado e bata novamente."}, {"q": "Posso usar só leite?", "a": "Gordura, rendimento e textura mudam. A fórmula inclui creme para maior cremosidade."}], "additional_time_minutes": 145}, "published": false, "editorial_status": "ready"}]$payload$::jsonb;
foods jsonb := $foods$[]$foods$::jsonb;
aliases jsonb := $aliases$[{"slug": "leche", "alias": "leche entera pasteurizada no UHT"}, {"slug": "crema-de-leche", "alias": "crema de leche pasteurizada, aproximadamente 35 % de grasa"}, {"slug": "limon", "alias": "zumo de limón recién exprimido y colado"}, {"slug": "sal", "alias": "sal fina"}]$aliases$::jsonb;
x jsonb; a jsonb; v public.recipes; made public.recipes; source_id uuid; group_id uuid;
BEGIN
PERFORM set_config('request.jwt.claim.sub','2caf0bab-d7e8-4d52-9910-d79799c27072',true);
IF NOT public.is_admin() THEN RAISE EXCEPTION 'Admin context missing'; END IF;
IF jsonb_array_length(payload)<>7 THEN RAISE EXCEPTION 'Need seven languages'; END IF;
IF EXISTS(SELECT 1 FROM public.recipes r JOIN jsonb_array_elements(payload) e ON r.public_path=e->>'public_path' OR (r.language=e->>'language' AND r.slug=e->>'slug')) THEN RAISE EXCEPTION 'Recipe already exists'; END IF;
IF EXISTS(SELECT 1 FROM public.content_pages p JOIN jsonb_array_elements(payload) e ON p.public_path=e->>'public_path') OR EXISTS(SELECT 1 FROM public.content_redirects r JOIN jsonb_array_elements(payload) e ON r.source_path=e->>'public_path') THEN RAISE EXCEPTION 'Route collision'; END IF;
FOR a IN SELECT value FROM jsonb_array_elements(foods) LOOP
 INSERT INTO public.ingredients(slug,name,normalized_name,description,status,searchable,indexable)
 SELECT a->>'slug',a->>'name',lower(a->>'name'),'Ingrediente para elaboraciones lácteas domésticas.','canonical',true,false WHERE NOT EXISTS(SELECT 1 FROM public.ingredients WHERE slug=a->>'slug');
END LOOP;
FOR a IN SELECT value FROM jsonb_array_elements(aliases) LOOP
 IF NOT EXISTS(SELECT 1 FROM public.ingredients WHERE slug=a->>'slug' AND status='canonical') THEN RAISE EXCEPTION 'Missing ingredient %',a; END IF;
 IF EXISTS(SELECT 1 FROM public.ingredient_aliases ia JOIN public.ingredients i ON i.id=ia.ingredient_id WHERE lower(trim(ia.alias))=lower(trim(a->>'alias')) AND i.slug<>a->>'slug' AND i.status='canonical') THEN RAISE EXCEPTION 'Alias collision %',a; END IF;
 INSERT INTO public.ingredient_aliases(ingredient_id,alias,normalized_alias) SELECT id,a->>'alias',lower(a->>'alias') FROM public.ingredients WHERE slug=a->>'slug' AND status='canonical' ON CONFLICT(ingredient_id,normalized_alias) DO NOTHING;
END LOOP;
FOR x IN SELECT value FROM jsonb_array_elements(payload) LOOP
 v:=jsonb_populate_record(NULL::public.recipes,x);
 IF v.language='es' THEN
  made:=public.create_recipe(v.language,v.slug,v.title,v.excerpt,v.ingredients,v.steps,v.category,v.prep_time_minutes,v.cook_time_minutes,v.servings,v.image_url,false,v.public_path);
  source_id:=made.id;group_id:=made.recipe_group_id;
 ELSE
  made:=public.create_recipe_translation(source_id,v.language,v.slug,v.title,v.excerpt,v.ingredients,v.steps,v.category,v.prep_time_minutes,v.cook_time_minutes,v.servings,v.image_url,false,v.public_path);
 END IF;
 UPDATE public.recipes SET content_html=v.content_html,summary=v.summary,notes=v.notes,difficulty=v.difficulty,course=v.course,cuisine=v.cuisine,total_time_minutes=v.total_time_minutes,keywords=v.keywords,nutrition=v.nutrition,gallery=v.gallery,video_urls=v.video_urls,seo=v.seo,editorial_status='ready',ready_at=now() WHERE id=made.id;
END LOOP;
IF (SELECT count(*) FROM public.recipes WHERE recipe_group_id=group_id)<>7 THEN RAISE EXCEPTION 'Incomplete group'; END IF;
IF (SELECT count(*) FROM public.recipe_ingredients WHERE recipe_id=source_id)<>4 OR EXISTS(SELECT 1 FROM public.recipe_ingredient_pending WHERE recipe_id=source_id) THEN RAISE EXCEPTION 'Unresolved ingredients'; END IF;
FOR v IN SELECT * FROM public.recipes WHERE recipe_group_id=group_id LOOP
 PERFORM public.update_recipe(v.id,v.slug,v.title,v.excerpt,v.ingredients,v.steps,v.category,v.prep_time_minutes,v.cook_time_minutes,v.servings,v.image_url,true);
 UPDATE public.recipes SET editorial_status='published' WHERE id=v.id;
END LOOP;
END $dairy$;
SELECT language,public_path,published FROM public.recipes WHERE recipe_group_id=(SELECT recipe_group_id FROM public.recipes WHERE language='es' AND slug='queso-crema-casero') ORDER BY language;
